import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易緯坤靈圖〔漢〕鄭玄","description":"易緯坤靈圖 - 易緯坤靈圖〔漢〕鄭玄","frontmatter":{"title":"易緯坤靈圖〔漢〕鄭玄","description":"易緯坤靈圖 - 易緯坤靈圖〔漢〕鄭玄"},"headers":[],"relativePath":"classics/yiwei-kunlingtu/001.md","filePath":"classics/yiwei-kunlingtu/001.md"}'),r={name:"classics/yiwei-kunlingtu/001.md"};function c(l,a,o,d,p,u){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易緯坤靈圖〔漢〕鄭玄",tabindex:"-1"},[n("易緯坤靈圖〔漢〕鄭玄 "),e("a",{class:"header-anchor",href:"#易緯坤靈圖〔漢〕鄭玄","aria-label":"Permalink to “易緯坤靈圖〔漢〕鄭玄”"},"​")],-1),e("p",null,"欽定四庫全書易緯坤靈圖 ​漢 鄭康成 注邱序曰：天經曰：「乾，元亨利貞。」爻曰：「飛龍在天，利見大人。」 ​謂易為天經者，聖人所製作。乾有四德，「飛龍在天」，此聖人以至德居天子位也。序此之言說之也。故德配天地，天地不私公位，稱之曰「帝」。 ​古者聖人德如此也，不私公位，不傳之子孫，禪於能者，與天同，故以天稱之也。故堯，天之精陽，萬物莫不從者，故乾居西北，乾用事，萬物蟄伏。致乎萬物蟄伏，故能致乎萬人之化。 ​「立天之道，曰陰與陽」，言堯乃天之陽精所生，所以能為明君，而能假人也。萬物蟄伏，象施化功成，人人化，故然也。經曰「用九」， ​堯時賢聖為聖德化於天下故耳。天之所首之，故經以明之。經曰：震下乾上，旡妄，天精起。 ​起猶立。乾為天，震為長子，天生長子，聖人立為天子，天下之人各得所，天所獲旡妄也。帝必有洪水之災，天生聖人使殺之，故言「乃統天」也。 ​初九震在子，坎為水，又年與艮同體，艮為山，水而漸山，是大水為人害，天故生聖君。堯求命之，是亦堯辜也。與乾統天之功同。邱括義：因象助類。辭曰：天無雲而雷，先王以茂對時育萬物。 ​茂，勉也。對，遂。育，長也。天之將雨，先必興雲而後雷。今乾在上，下無坎而有震，是以雷行天下，無雲而雷。洪水之時，人苦雨之多，故堯於是茂勉，遂其教令，以養萬物。以是眾庶艱食，得以餬口焉。經曰：乾下艮上，大畜。天災將至，預畜而待之，人免於飢，故曰元亨。 ​按：乾元序制記內「賢子孫繼世而立」云云，疑此處註文上下皆通，各載其性，故曰利貞。 ​載之時，言得值也。言待堯養萬物，將歲不飢，長幼情性，人自各得如此也。至德之萌，五星若連珠，日月如合璧。天精起鬥口有位，雞鳴鬥運行復始，莫敢當之。黃星笰於北斗，必以戊己日，其先無芒，行文元武動事，莫之敢距。 ​按繹史引坤靈圖雲：「伏羲立九部而民易理。」又云：「?陽者火，火惡水，故食不飲。桑者上之液，木生火，故?以三月草頰會精，合相食。」隋書引坤靈圖雲：「河龍以正月辰見，白龍與五黑龍鬥，白龍陵，故泰人有命。」鄭康成雲：「陵當為除。」今皆無其文。蓋此本非完書，且有錯入乾元序制記萹內者。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
